// ─── Batch 4 | Extract Contact ID ────────────────────────────────────────────
// HubSpot upsert returns the contact object after create or update.
// Contact ID field: 'vid' (v1 compat wrapper) or 'id' (v3 native response).
// Merges HubSpot identity with full scored payload from the sub-workflow trigger.
// Throws on missing ID — fail-fast prevents downstream deal from orphaning.
// Re-sets candidate customData so error handler has context if this sub-workflow fails.
// ─────────────────────────────────────────────────────────────────────────────

const hsContact = $input.first().json;
const scored    = $('When Called by Workflow').first().json;

// ── Re-set execution context (customData does not cross sub-workflow boundaries) ──
$execution.customData.set('candidate_name',  scored.candidateName  ?? 'N/A');
$execution.customData.set('candidate_email', scored.candidateEmail ?? 'N/A');
$execution.customData.set('stage',           'crm_routing');

// Contact ID: check all known HubSpot response field names
const hubspotContactId = String(
  hsContact.vid          ??
  hsContact.id           ??
  hsContact.hs_object_id ??
  ''
);

if (!hubspotContactId) {
  throw new Error(
    'HubSpot upsert returned no contact ID. ' +
    'Checked: vid, id, hs_object_id. Response keys: ' +
    Object.keys(hsContact).join(', ')
  );
}

return [{
  json: {
    ...scored,
    hubspotContactId,
    hubspotContactCreatedAt: new Date().toISOString()
  }
}];

// ─── Batch 4 | Merge CRM IDs ─────────────────────────────────────────────────
// Extracts Deal ID from HubSpot deal create response.
// Merges contactId + dealId into full scored payload for Batch 5 (Comms Routing).
// Updates $execution.customData so error handler includes CRM IDs in Slack alerts
// if Batch 5/6/7 fail after CRM records are created.
// ─────────────────────────────────────────────────────────────────────────────

const hsDeal = $input.first().json;
const item   = $('Extract Contact ID').first().json;

// Deal ID: check all known HubSpot response field names
const hubspotDealId = String(
  hsDeal.dealId        ??
  hsDeal.id            ??
  hsDeal.hs_object_id  ??
  ''
);

if (!hubspotDealId) {
  throw new Error(
    'HubSpot deal create returned no deal ID. ' +
    'Checked: dealId, id, hs_object_id. Response keys: ' +
    Object.keys(hsDeal).join(', ')
  );
}

// Propagate CRM IDs to execution context (error handler reads these)
$execution.customData.set('hubspot_contact_id', item.hubspotContactId);
$execution.customData.set('hubspot_deal_id',    hubspotDealId);

return [{
  json: {
    ...item,
    hubspotDealId,
    crmRoutedAt: new Date().toISOString()
  }
}];
